import{_ as t,c as e,o,am as c}from"./chunks/framework.CiCI_NbS.js";const p=JSON.parse('{"title":"CustomVina 接口参考","description":"","frontmatter":{"prev":{"text":"从一个矩形开始","link":"/docs/pogget/custom-vina"},"next":{"text":"宿主输入","link":"/docs/pogget/custom-vina/inputs"}},"headers":[],"relativePath":"docs/pogget/custom-vina/reference.md","filePath":"docs/pogget/custom-vina/reference.md"}'),r={name:"docs/pogget/custom-vina/reference.md"};function a(n,d,i,l,h,s){return o(),e("div",null,d[0]||(d[0]=[c('<h1 id="customvina-接口参考" tabindex="-1">CustomVina 接口参考 <a class="header-anchor" href="#customvina-接口参考" aria-label="Permalink to &quot;CustomVina 接口参考&quot;">​</a></h1><p>本页按类型列出当前语言的图元、属性、表达式、状态和面板控件。每张表左侧为可填写的名称，右侧说明用途；数值范围来自当前绘制与布局校验。另见<a href="./inputs.html">宿主输入</a>、<a href="./actions.html">内部动作</a>、<a href="./slots.html">绘制阶段</a>和<a href="./labels.html">内置文案</a>。</p><h2 id="文件结构与值类型" tabindex="-1">文件结构与值类型 <a class="header-anchor" href="#文件结构与值类型" aria-label="Permalink to &quot;文件结构与值类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th>声明位置</th><th>用途</th></tr></thead><tbody><tr><td><code>Preset { dependsOn: &quot;名称&quot; }</code></td><td>单层依赖声明；只能有一个独立基础，不带扩展名和路径</td></tr><tr><td><code>组件名 { ... }</code></td><td>顶层组件，名称自定义；同层不允许重复</td></tr><tr><td>组件的 <code>label</code>、<code>description</code>、<code>icon</code></td><td>设置面板中该组件分组的标题、说明和图标</td></tr><tr><td><code>ui { ... }</code></td><td>声明可保存的面板参数</td></tr><tr><td><code>vars { ... }</code></td><td>声明可引用的表达式，适合尺寸、颜色等派生值</td></tr><tr><td><code>state { ... }</code></td><td>声明每个收纳盒独立的会话状态</td></tr><tr><td><code>view { ... }</code></td><td>声明视图树；子块默认是子视图，专用元数据块除外</td></tr><tr><td><code>Panel { ... }</code></td><td>个性化设置面板的专用布局组件，见本页末尾</td></tr></tbody></table><table tabindex="0"><thead><tr><th>值类型</th><th>示例与含义</th></tr></thead><tbody><tr><td>数值</td><td><code>12</code>、<code>-4.5</code>，必须有限；尺寸默认 DIP，时间默认秒</td></tr><tr><td>毫秒</td><td><code>160ms</code> 等于数值 <code>0.16</code></td></tr><tr><td>布尔</td><td><code>true</code>、<code>false</code></td></tr><tr><td>字符串</td><td><code>&quot;Segoe UI&quot;</code>；支持 <code>\\n</code>、<code>\\r</code>、<code>\\t</code>、<code>\\uXXXX</code>、<code>\\&quot;</code>、<code>\\\\</code> 转义</td></tr><tr><td>标识符</td><td><code>pogget.action.view.toggle</code>、<code>pogget.label.titleClassic</code>，作为文本 ID 使用</td></tr><tr><td>引用</td><td><code>${vars.radius}</code>、<code>${pogget.width}</code>，取其他属性或宿主输入的值</td></tr><tr><td>颜色</td><td><code>rgb(30, 144, 255)</code> 或 <code>0..16777215</code> 的 COLORREF 整数；不是 CSS 颜色字符串</td></tr></tbody></table><h2 id="图元类型-type" tabindex="-1">图元类型 type <a class="header-anchor" href="#图元类型-type" aria-label="Permalink to &quot;图元类型 type&quot;">​</a></h2><table tabindex="0"><thead><tr><th><code>type</code></th><th>用途与默认行为</th></tr></thead><tbody><tr><td><code>group</code></td><td>组织子视图；坐标、不透明度、可见性、启用状态和裁剪影响子节点，默认不画背景</td></tr><tr><td><code>rect</code></td><td>矩形/圆角矩形，默认绘制填充，可加边框和阴影</td></tr><tr><td><code>rectangle</code></td><td><code>rect</code> 的别名</td></tr><tr><td><code>button</code></td><td>与 <code>rect</code> 相同的绘制类型；通过 <code>action</code>、<code>holdAction</code> 或 <code>toggle</code> 接入交互</td></tr><tr><td><code>container</code></td><td><code>rect</code> 的别名，不会额外创建一个 Pogget 收纳盒</td></tr><tr><td><code>solid</code></td><td>实色方角矩形；保留方角，不使用 <code>radius</code> 绘制圆角</td></tr><tr><td><code>text</code></td><td>绘制 <code>label</code> 提供的文字</td></tr><tr><td><code>icon</code></td><td>绘制字体图标字符，使用 <code>icon</code> 与对应 <code>font</code></td></tr><tr><td><code>image</code></td><td>绘制 WIC 图片、Shell 图标或本次绘制的命名位图</td></tr><tr><td><code>glass</code></td><td>玻璃高光/光效层，<code>background</code> 参与亮度计算，不自动填充背景</td></tr><tr><td><code>content</code></td><td>绘制宿主登记的命名内容资源，如 Markdown；只在当前绘制调用中使用</td></tr></tbody></table><p>建议始终显式填写 <code>type</code>。省略时，有子视图的节点默认为 <code>group</code>，没有子视图的节点默认为 <code>text</code>。旧的 <code>type: &quot;texture&quot;</code> 已移除，应保留原图元并使用 <code>texture</code> 属性。</p><p><code>pogget.native.Header</code> 是<a href="./slots.html#header-兼容布局">布局兼容接口</a>。<code>pogget.native.Background</code>、<code>pogget.native.Tag</code>、<code>pogget.native.VinaIcon</code>、<code>pogget.native.Behavior</code> 是保留的旧组件标识，走兼容路径，不是通用绘图类型；新组件使用上表图元和对应 slot。</p><h2 id="布局与可见性" tabindex="-1">布局与可见性 <a class="header-anchor" href="#布局与可见性" aria-label="Permalink to &quot;布局与可见性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型、默认值与用途</th></tr></thead><tbody><tr><td><code>x</code>、<code>y</code></td><td>数值，默认 <code>0</code>，范围 ±32768；相对父视图的坐标</td></tr><tr><td><code>width</code>、<code>height</code></td><td>数值，默认 <code>40</code>，范围 <code>0..32768</code>；视图尺寸，不会自动撑满父节点</td></tr><tr><td><code>w</code>、<code>h</code></td><td>宽、高的兼容别名；同时存在时 <code>width</code>、<code>height</code> 优先</td></tr><tr><td><code>z</code></td><td>数值，默认 <code>0</code>，范围 ±32768；同级绘制层级，相同值按声明顺序排列</td></tr><tr><td><code>visible</code></td><td>布尔，默认 <code>true</code>；隐藏后不绘制、不命中，影响子视图</td></tr><tr><td><code>enabled</code></td><td>布尔，默认 <code>true</code>；控制交互是否启用，影响子视图</td></tr><tr><td><code>opacity</code></td><td>数值，默认 <code>1</code>，范围 <code>0..1</code>；整体不透明度，与父节点不透明度相乘</td></tr><tr><td><code>slot</code></td><td>字符串；指定宿主绘制阶段，子节点默认继承，见<a href="./slots.html">完整表</a></td></tr><tr><td><code>interaction</code></td><td>字符串；标记宿主交互范围，<code>title</code> 跟随标题状态，<code>icon</code> 用于文件图标范围；不产生重复绘制</td></tr><tr><td><code>role</code></td><td><code>interaction</code> 的兼容别名，显式 <code>interaction</code> 优先</td></tr></tbody></table><h3 id="裁剪" tabindex="-1">裁剪 <a class="header-anchor" href="#裁剪" aria-label="Permalink to &quot;裁剪&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>类型、默认值与用途</th></tr></thead><tbody><tr><td><code>clip</code></td><td>布尔，默认 <code>false</code>；按当前视图矩形裁剪自身及后代，并限制命中</td></tr><tr><td><code>clipRadius</code></td><td>数值，默认 <code>0</code>，范围 <code>0..32768</code>；裁剪圆角半径，需要启用 <code>clip</code></td></tr><tr><td><code>clipLayer</code></td><td>布尔，默认 <code>false</code>；使用共享蒙版合成层；正圆角也会启用该方式</td></tr><tr><td><code>clipAntialias</code></td><td><code>&quot;perPrimitive&quot;</code>（默认）或 <code>&quot;aliased&quot;</code>；裁剪抗锯齿方式</td></tr></tbody></table><h2 id="背景、纹理与边框" tabindex="-1">背景、纹理与边框 <a class="header-anchor" href="#背景、纹理与边框" aria-label="Permalink to &quot;背景、纹理与边框&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型、默认值与用途</th></tr></thead><tbody><tr><td><code>background</code></td><td>颜色，默认主题 <code>midnight</code>；指定填充颜色；非矩形图元需显式声明才有背景，<code>glass</code> 除外</td></tr><tr><td><code>fillOpacity</code></td><td>数值，默认 <code>1</code>，范围 <code>0..1</code>；填充不透明度；普通玻璃也读取此参数</td></tr><tr><td><code>radius</code></td><td>数值，默认 <code>0</code>，范围 <code>0..32768</code>；矩形、玻璃及受支持位图的圆角</td></tr><tr><td><code>cornerRadius</code></td><td><code>radius</code> 的兼容别名，显式 <code>radius</code> 优先</td></tr><tr><td><code>texture</code></td><td>布尔或 <code>0..64</code>；省略/<code>false</code> 为普通填充，<code>true</code>/数值 <code>0</code> 启用立体纹理，数值同时指定纹理描边宽度</td></tr><tr><td><code>border</code></td><td>数值，默认 <code>0</code>，范围 <code>0..64</code>；独立边框宽度</td></tr><tr><td><code>borderColor</code></td><td>颜色，默认主题 <code>white</code>；边框颜色</td></tr><tr><td><code>borderOpacity</code></td><td>数值，默认 <code>1</code>，范围 <code>0..1</code>；边框不透明度；光效也用它控制基础边缘</td></tr><tr><td><code>borderStyle</code></td><td><code>&quot;solid&quot;</code>（默认）或 <code>&quot;dash&quot;</code>；实线或虚线边框</td></tr><tr><td><code>borderOnly</code></td><td>布尔，默认 <code>false</code>；只画边框，跳过背景与纹理填充</td></tr><tr><td><code>blur</code></td><td>数值，默认 <code>0</code>，范围 <code>0..64</code>；使用现有材质后端绘制背景模糊</td></tr><tr><td><code>blurRenderer</code></td><td><code>&quot;title&quot;</code>（默认）或 <code>&quot;snapshot&quot;</code>；分别选择标题材质和快照模糊后端；快照采样原点须非负</td></tr></tbody></table><p><code>rect</code>、<code>rectangle</code>、<code>button</code>、<code>container</code>、<code>solid</code> 可直接使用 <code>texture</code>。<code>group</code>、<code>text</code>、<code>icon</code>、<code>image</code>、<code>content</code> 还需显式 <code>background</code>。纹理不替代独立边框，仍可搭配虚线；<code>glass</code> 没有背景填充，不能靠 <code>texture</code> 生成实体表面。</p><h3 id="阴影" tabindex="-1">阴影 <a class="header-anchor" href="#阴影" aria-label="Permalink to &quot;阴影&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>默认值、范围与用途</th></tr></thead><tbody><tr><td><code>shadowOpacity</code></td><td><code>0</code>，<code>0..1</code>；外阴影不透明度</td></tr><tr><td><code>shadowColor</code></td><td>黑色 COLORREF；外阴影颜色</td></tr><tr><td><code>shadowX</code>、<code>shadowY</code></td><td><code>0</code>、<code>4</code>，±256；外阴影水平、垂直偏移</td></tr><tr><td><code>shadowBlur</code></td><td><code>16</code>，<code>0..128</code>；外阴影模糊范围</td></tr><tr><td><code>shadowQuality</code></td><td><code>4</code>，<code>1..32</code>；外阴影绘制采样质量</td></tr><tr><td><code>innerShadowOpacity</code></td><td><code>0</code>，<code>0..1</code>；内阴影不透明度</td></tr><tr><td><code>innerShadowInset</code></td><td><code>0.5</code>，<code>0..256</code>；内阴影内缩量</td></tr><tr><td><code>innerShadowDepth</code></td><td><code>2</code>，<code>0..256</code>；内阴影深度</td></tr><tr><td><code>innerShadowLowerOpacity</code></td><td><code>0</code>，<code>0..1</code>；下沿内阴影强度</td></tr></tbody></table><h3 id="玻璃与光效" tabindex="-1">玻璃与光效 <a class="header-anchor" href="#玻璃与光效" aria-label="Permalink to &quot;玻璃与光效&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>默认值、范围与用途</th></tr></thead><tbody><tr><td><code>glassRenderer</code></td><td><code>&quot;standard&quot;</code> 或 <code>&quot;lightEffect&quot;</code>；默认 <code>standard</code>，旧值 <code>liquid</code> 已迁移</td></tr><tr><td><code>glassActive</code></td><td><code>false</code>；普通玻璃高光开关；<code>lightEffect</code> 不受此开关控制</td></tr><tr><td><code>glassOpacity</code></td><td><code>1</code>，<code>0..1</code>；玻璃/光效强度</td></tr><tr><td><code>glassBorder</code></td><td><code>1</code>，<code>0..64</code>；玻璃边缘宽度</td></tr><tr><td><code>glassPointerX</code>、<code>glassPointerY</code></td><td>数值，±32768；显式指针目标坐标，必须同时声明；省略则使用原有鼠标采样</td></tr><tr><td><code>glassTintEnabled</code></td><td>布尔；默认在声明 <code>glassTintColor</code> 时启用，否则关闭；控制是否着色</td></tr><tr><td><code>glassTintColor</code></td><td>颜色，默认黑色；着色颜色</td></tr><tr><td><code>glassTintAmount</code></td><td><code>0</code>，<code>0..1</code>；着色比例</td></tr><tr><td><code>glassCustomEdge</code></td><td><code>false</code>；光效使用 <code>borderColor</code> 作为自定义基础边缘颜色</td></tr></tbody></table><p>玻璃层的 <code>background</code> 用于亮度计算。需要底色时先画 <code>rect</code> 再叠加 <code>glass</code>。光效的基础边缘读取 <code>borderOpacity</code>；普通玻璃继续读取 <code>fillOpacity</code>。完整示例见<a href="./../custom-vina.html#叠加玻璃高光">入门教程</a>。</p><h2 id="文字与字体图标" tabindex="-1">文字与字体图标 <a class="header-anchor" href="#文字与字体图标" aria-label="Permalink to &quot;文字与字体图标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>默认值、范围与用途</th></tr></thead><tbody><tr><td><code>label</code></td><td>字符串或内置文案 ID；文字内容</td></tr><tr><td><code>icon</code></td><td>字符串；字体图标字符；与 <code>label</code> 同时存在时优先使用 <code>icon</code></td></tr><tr><td><code>font</code></td><td><code>&quot;Segoe UI&quot;</code>；字体族；Font Awesome 图标使用 <code>&quot;Font Awesome 6 Free Solid&quot;</code></td></tr><tr><td><code>textSize</code></td><td><code>14</code>，<code>0.001..256</code>；字号，单位 DIP</td></tr><tr><td><code>color</code></td><td>主题 <code>white</code>；文字颜色</td></tr><tr><td><code>textX</code></td><td><code>0</code>，±32768；文字相对视图的水平偏移</td></tr><tr><td><code>textY</code></td><td>默认 <code>(height - textSize) / 2</code>，±32768；文字垂直偏移</td></tr><tr><td><code>align</code></td><td>默认 <code>&quot;center&quot;</code>；文字对齐，通用布局使用 <code>&quot;left&quot;</code>、<code>&quot;center&quot;</code>、<code>&quot;right&quot;</code>，具体由文字后端读取</td></tr><tr><td><code>emphasized</code></td><td><code>false</code>；强调状态，供对应原生文字/标签绘制使用</td></tr><tr><td><code>textLiteral</code></td><td><code>false</code>；启用后文字按原文显示，不解析为多语言文案 ID</td></tr><tr><td><code>textNoWrap</code></td><td><code>false</code>；禁止自动换行，用于支持此选项的文字后端</td></tr><tr><td><code>textClip</code></td><td><code>false</code>；命名文本布局绘制时启用 DirectWrite 的 CLIP 标志</td></tr><tr><td><code>textFloatPosition</code></td><td><code>false</code>；普通文字使用浮点位置</td></tr><tr><td><code>textOmitUnits</code></td><td><code>0</code>，<code>0..32768</code>；正数时按 Unicode 显示单位预算省略文字，<code>0</code> 不启用</td></tr><tr><td><code>textColorFont</code></td><td><code>false</code>；直接布局后端启用彩色字体</td></tr><tr><td><code>textAppFonts</code></td><td><code>false</code>；直接布局后端使用应用字体集合</td></tr><tr><td><code>textRenderer</code></td><td>默认空字符串；选取下表文字后端</td></tr></tbody></table><table tabindex="0"><thead><tr><th><code>textRenderer</code></th><th>用途</th></tr></thead><tbody><tr><td>省略或 <code>&quot;&quot;</code></td><td>默认文字/图标绘制路径</td></tr><tr><td><code>&quot;glyph&quot;</code></td><td>原生图标字符绘制</td></tr><tr><td><code>&quot;dwrite2&quot;</code></td><td>现有普通文字与阴影后端</td></tr><tr><td><code>&quot;dwrite3&quot;</code></td><td>现有半粗文字与阴影后端</td></tr><tr><td><code>&quot;direct&quot;</code></td><td>原始 DirectWrite 布局，支持浮点字号、彩色/应用字体和零宽布局；祖先组负责裁剪</td></tr><tr><td><code>&quot;resource&quot;</code></td><td>使用 <code>source</code> 指定的本次绘制命名文本布局；字体和对齐来自宿主测量策略</td></tr></tbody></table><h3 id="文字阴影" tabindex="-1">文字阴影 <a class="header-anchor" href="#文字阴影" aria-label="Permalink to &quot;文字阴影&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性</th><th>默认值、范围与用途</th></tr></thead><tbody><tr><td><code>textShadowOpacity</code></td><td><code>0</code>，<code>0..1</code>；文字阴影不透明度</td></tr><tr><td><code>textShadowColor</code></td><td>黑色；文字阴影颜色</td></tr><tr><td><code>textShadowX</code>、<code>textShadowY</code></td><td><code>0</code>、<code>1</code>，±256；文字阴影偏移</td></tr><tr><td><code>textShadowBlur</code></td><td><code>2</code>，<code>0..128</code>；文字阴影模糊范围</td></tr><tr><td><code>textShadowQuality</code></td><td><code>3</code>，<code>1..32</code>；文字阴影采样质量</td></tr><tr><td><code>textShadowOnly</code></td><td><code>false</code>；只画文字阴影</td></tr><tr><td><code>textShadowRingOpacity</code></td><td><code>1</code>，<code>0..1</code>；文字阴影环的不透明度</td></tr><tr><td><code>textShadowScaleX</code>、<code>textShadowScaleY</code></td><td><code>1</code>，<code>0..8</code>；文字阴影的横向、纵向缩放</td></tr></tbody></table><h2 id="图片与同步内容" tabindex="-1">图片与同步内容 <a class="header-anchor" href="#图片与同步内容" aria-label="Permalink to &quot;图片与同步内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>默认值、范围与用途</th></tr></thead><tbody><tr><td><code>source</code></td><td>图片路径或宿主资源名；<code>content</code> 和资源文字也使用此字段</td></tr><tr><td><code>src</code></td><td><code>source</code> 的别名，显式 <code>source</code> 优先</td></tr><tr><td><code>imageRenderer</code></td><td><code>&quot;wic&quot;</code>（默认）：WIC 图片；<code>&quot;shell&quot;</code>：Shell 图标；<code>&quot;resource&quot;</code>：本次绘制的命名位图</td></tr><tr><td><code>imageFit</code></td><td><code>&quot;stretch&quot;</code>（默认）：拉伸；<code>&quot;contain&quot;</code>：保持比例完整放入目标矩形</td></tr><tr><td><code>imageCrop</code></td><td><code>false</code>；对 WIC/资源位图启用源矩形裁切</td></tr><tr><td><code>imageSourceX</code>、<code>imageSourceY</code></td><td><code>0</code>，<code>0..32768</code>；源图中的裁切起点，单位源图 DIP</td></tr><tr><td><code>imageSourceWidth</code>、<code>imageSourceHeight</code></td><td><code>0</code>，<code>0..32768</code>；源裁切大小；启用裁切但矩形为空时不绘制</td></tr><tr><td><code>imageScaleX</code>、<code>imageScaleY</code></td><td><code>1</code>，<code>0.001..8</code>；位图横纵缩放，与宿主变换组合</td></tr><tr><td><code>imagePivotX</code>、<code>imagePivotY</code></td><td><code>0</code>，±32768；缩放中心，使用宿主 DIP 坐标</td></tr><tr><td><code>contentScale</code></td><td><code>1</code>，<code>0.001..256</code>；同步内容缩放，以内容左上角为中心，在祖先裁剪建立后生效</td></tr></tbody></table><p>WIC/资源位图支持 <code>radius</code> 圆角；Shell 图标需要圆角时使用祖先组的 <code>clip</code> 与 <code>clipRadius</code>。裁切后的 <code>contain</code> 按源裁切区域比例排版。<code>resource</code>、<code>content</code> 只访问宿主本次登记的资源；缺少资源时不绘制，不能通过字符串创建原生函数。可用资源名见<a href="./slots.html#命名资源">资源表</a>。</p><h2 id="点击、悬停与动画" tabindex="-1">点击、悬停与动画 <a class="header-anchor" href="#点击、悬停与动画" aria-label="Permalink to &quot;点击、悬停与动画&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性或块</th><th>默认值、范围与用途</th></tr></thead><tbody><tr><td><code>action</code></td><td>短按执行的内部动作 ID，见<a href="./actions.html">完整动作表</a></td></tr><tr><td><code>holdAction</code></td><td>达到长按阈值后，有效释放时执行的动作 ID</td></tr><tr><td><code>holdDelay</code></td><td><code>0.4</code> 秒，<code>0..10</code>；长按判定阈值</td></tr><tr><td><code>hitPaddingX</code>、<code>hitPaddingY</code></td><td><code>0</code>，<code>0..256</code>；点击区域在横纵方向向外扩展的距离</td></tr><tr><td><code>toggle</code></td><td>字符串字面量，如 <code>&quot;state.expanded&quot;</code>；短按翻转已声明的布尔状态，再执行可选 <code>action</code></td></tr><tr><td><code>hover { ... }</code></td><td>悬停目标属性；支持的数值与颜色由现有悬停进度插值</td></tr><tr><td><code>transition</code></td><td><code>0.2</code> 秒，<code>0..10</code>；进入悬停时长</td></tr><tr><td><code>unhoverTransition</code></td><td>默认跟随 <code>transition</code>，<code>0..10</code>；离开悬停时长</td></tr><tr><td><code>pressDuration</code></td><td><code>0.15</code> 秒，<code>0..10</code>；原生按钮按压动画时长</td></tr><tr><td><code>releaseDuration</code></td><td><code>0.3</code> 秒，<code>0..10</code>；原生按钮释放动画时长</td></tr><tr><td><code>pressScale</code></td><td><code>0.85</code>，<code>0..8</code>；原生按钮按压目标缩放</td></tr><tr><td><code>holdDuration</code></td><td><code>0.3</code> 秒，<code>0..10</code>；原生按钮长按反馈动画时长</td></tr><tr><td><code>holdScale</code></td><td><code>0.9</code>，<code>0..8</code>；原生按钮长按目标缩放</td></tr><tr><td><code>holdOffset</code></td><td><code>5</code>，±256；原生按钮长按反馈位移</td></tr></tbody></table><p>通用节点的 <code>hover</code> 使用悬停动画器；<code>press*</code>、<code>hold*</code> 反馈参数由接入对应能力的原生按钮读取，不会自动给所有矩形增加按压形变。可通过下列只读悬停输入自行计算几何：</p><table tabindex="0"><thead><tr><th>引用</th><th>用途</th></tr></thead><tbody><tr><td><code>${self.hovered}</code></td><td>当前视图是否处于悬停目标状态，布尔值</td></tr><tr><td><code>${self.hoverProgress}</code></td><td>当前悬停动画进度，<code>0..1</code></td></tr><tr><td><code>${parent.hovered}</code>、<code>${parent.hoverProgress}</code></td><td>父视图的相同输入</td></tr><tr><td><code>${组件.view.节点.hovered}</code>、<code>${组件.view.节点.hoverProgress}</code></td><td>按完整视图路径读取悬停状态</td></tr></tbody></table><h3 id="自定义悬停区域-hoverregion" tabindex="-1">自定义悬停区域 hoverRegion <a class="header-anchor" href="#自定义悬停区域-hoverregion" aria-label="Permalink to &quot;自定义悬停区域 hoverRegion&quot;">​</a></h3><p>在视图下添加 <code>hoverRegion { ... }</code> 可区分进入区域与保持区域。这里使用<strong>世界 DIP 坐标</strong>，不是相对父节点坐标。</p><table tabindex="0"><thead><tr><th>字段</th><th>用途</th></tr></thead><tbody><tr><td><code>x</code>、<code>y</code>、<code>width</code>、<code>height</code></td><td>指针进入悬停的矩形；省略字段使用当前视图矩形；宽高非负</td></tr><tr><td><code>retainX</code>、<code>retainY</code>、<code>retainWidth</code>、<code>retainHeight</code></td><td>悬停后保持状态的矩形；省略字段跟随进入矩形，适合展开后扩大保持范围</td></tr><tr><td><code>enabled</code></td><td>是否启用该区域；视图隐藏、禁用或指针离开会取消悬停</td></tr></tbody></table><h3 id="本地状态-state" tabindex="-1">本地状态 state <a class="header-anchor" href="#本地状态-state" aria-label="Permalink to &quot;本地状态 state&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Preset { dependsOn: &quot;Pogget_Std&quot; }</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>ExpandableCard {</span></span>\n<span class="line"><span>  state { expanded: false, count: 0, caption: &quot;详情&quot; },</span></span>\n<span class="line"><span>  view {</span></span>\n<span class="line"><span>    type: &quot;button&quot;, x: 16, y: 64,</span></span>\n<span class="line"><span>    width: ${state.expanded} ? 240 : 100,</span></span>\n<span class="line"><span>    height: 40,</span></span>\n<span class="line"><span>    label: ${state.caption}, textLiteral: true,</span></span>\n<span class="line"><span>    toggle: &quot;state.expanded&quot;</span></span>\n<span class="line"><span>  }</span></span>\n<span class="line"><span>}</span></span></code></pre></div><p>状态默认值只接受布尔、有限数值或字符串字面量，可用负数。<code>toggle</code> 只翻转布尔变量；长按执行 <code>holdAction</code> 时不翻转。状态按收纳盒隔离，同一预设兼容热更新时保留，重启或切换预设时重置。要持久保存真实视图/折叠设置，应使用内部动作；要保存面板参数，使用 <code>ui</code>。</p><h2 id="表达式与函数" tabindex="-1">表达式与函数 <a class="header-anchor" href="#表达式与函数" aria-label="Permalink to &quot;表达式与函数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>写法</th><th>用途</th></tr></thead><tbody><tr><td><code>+</code>、<code>-</code>、<code>*</code>、<code>/</code>、<code>%</code>、<code>^</code></td><td>加、减、乘、除、浮点余数、幂；除数不能为零</td></tr><tr><td><code>==</code>、<code>!=</code>、<code>&lt;</code>、<code>&lt;=</code>、<code>&gt;</code>、<code>&gt;=</code></td><td>比较，返回布尔值</td></tr><tr><td><code>&amp;&amp;</code>、<code>||</code>、<code>!</code></td><td>逻辑与、或、非</td></tr><tr><td><code>条件 ? 值一 : 值二</code></td><td>条件选择；表达式采用栈式求值，不要依赖分支短路来避开除零等错误</td></tr><tr><td><code>pi</code></td><td>圆周率常量</td></tr><tr><td><code>min(a,b)</code>、<code>max(a,b)</code></td><td>两个值的较小/较大值</td></tr><tr><td><code>clamp(v,lo,hi)</code></td><td>将数值限制在闭区间内，要求 <code>lo &lt;= hi</code></td></tr><tr><td><code>abs(v)</code></td><td>绝对值</td></tr><tr><td><code>floor(v)</code>、<code>ceil(v)</code></td><td>向下/向上取整</td></tr><tr><td><code>round(v)</code></td><td>四舍五入到整数，半值按 C++ <code>round</code> 规则远离零</td></tr><tr><td><code>trunc(v)</code></td><td>向零截断，如 <code>trunc(-1.8) = -1</code></td></tr><tr><td><code>f32(v)</code></td><td>转为单精度再返回数值，用于保留原生浮点布局的舍入</td></tr><tr><td><code>sqrt(v)</code></td><td>平方根，输入须非负</td></tr><tr><td><code>pow(a,b)</code></td><td>幂，与 <code>a ^ b</code> 相同</td></tr><tr><td><code>hypot(x,y)</code></td><td>计算 <code>sqrt(x*x + y*y)</code></td></tr><tr><td><code>rgb(r,g,b)</code></td><td>构造 COLORREF，各通道截断并限制到 <code>0..255</code></td></tr><tr><td><code>red(c)</code>、<code>green(c)</code>、<code>blue(c)</code></td><td>读取 COLORREF 的红、绿、蓝通道</td></tr><tr><td><code>average(c)</code></td><td>读取颜色通道的整数平均亮度</td></tr><tr><td><code>fade(c,amount)</code></td><td>兼容原生亮度调整：平均亮度大于 128 时减去 <code>amount</code>，否则加上；调整量先向零截断，范围 ±255，各通道限制到 <code>0..255</code></td></tr></tbody></table><p><code>fade()</code> 不是不透明度函数，也不是始终变亮/变暗。字符串、布尔与数值的最终使用必须符合目标属性类型。没有循环、脚本和任意函数调用。</p><table tabindex="0"><thead><tr><th>引用形式</th><th>查找范围</th></tr></thead><tbody><tr><td><code>${self.width}</code></td><td>当前块的属性；兼容形式 <code>${self.width.value}</code> 也可用</td></tr><tr><td><code>${parent.width}</code></td><td>父块属性</td></tr><tr><td><code>${vars.name}</code></td><td>当前组件的派生变量</td></tr><tr><td><code>${ui.Name.value}</code></td><td>当前组件的面板参数值</td></tr><tr><td><code>${state.name}</code></td><td>当前组件的会话状态</td></tr><tr><td><code>${Component.vars.name}</code></td><td>其他组件的完整属性路径</td></tr><tr><td><code>${pogget.width}</code> 等</td><td>宿主只读输入，见<a href="./inputs.html">完整输入表</a></td></tr></tbody></table><h2 id="设置控件-ui" tabindex="-1">设置控件 ui <a class="header-anchor" href="#设置控件-ui" aria-label="Permalink to &quot;设置控件 ui&quot;">​</a></h2><p>每个 <code>ui</code> 子块声明一个控件，显式写 <code>type</code> 和 <code>control</code>。除按钮外提供 <code>default</code>，数值滑块同时填写 <code>min</code>、<code>max</code>、<code>step</code>。<code>choice</code> 的默认值是从 0 开始的选项序号。</p><table tabindex="0"><thead><tr><th><code>control</code></th><th><code>type</code> 与用途</th></tr></thead><tbody><tr><td><code>slider</code></td><td><code>number</code>；数值滑块</td></tr><tr><td><code>number</code></td><td><code>number</code>；当前映射到同一数值滑块</td></tr><tr><td><code>switch</code></td><td><code>boolean</code>；开关，默认值须为布尔</td></tr><tr><td><code>toggle</code></td><td><code>switch</code> 的别名</td></tr><tr><td><code>choice</code></td><td>通常为 <code>number</code>；通过 <code>choices</code> 或 <code>options</code> 声明下拉选项</td></tr><tr><td><code>select</code></td><td><code>choice</code> 的别名</td></tr><tr><td><code>text</code></td><td><code>string</code>；文本编辑控件</td></tr><tr><td><code>edit</code></td><td><code>text</code> 的别名</td></tr><tr><td><code>color</code></td><td><code>number</code>；颜色编辑器，值为 COLORREF</td></tr><tr><td><code>button</code></td><td>动作按钮，通过 <code>action</code> 调用内部动作，无需 <code>default</code></td></tr><tr><td><code>font</code></td><td><code>string</code>；字体选择，保存字体族名称</td></tr></tbody></table><h3 id="控件字段" tabindex="-1">控件字段 <a class="header-anchor" href="#控件字段" aria-label="Permalink to &quot;控件字段&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>用途</th></tr></thead><tbody><tr><td><code>label</code></td><td>控件标题，可用内置文案 ID</td></tr><tr><td><code>type</code></td><td>值类型，常用 <code>number</code>、<code>boolean</code>、<code>string</code></td></tr><tr><td><code>control</code></td><td>上表控件名称</td></tr><tr><td><code>default</code></td><td>初始值，必须与控件类型匹配</td></tr><tr><td><code>min</code>、<code>max</code>、<code>step</code></td><td>数值下限、上限、步进，步进须大于零</td></tr><tr><td><code>bind</code></td><td>原生设置绑定名，见下表；省略则保存该预设自己的参数</td></tr><tr><td><code>value</code></td><td>运行时当前值，通常用 <code>${ui.字段名.value}</code> 读取，不用它代替 <code>default</code></td></tr><tr><td><code>visible</code></td><td>是否在面板显示，可使用表达式</td></tr><tr><td><code>choices</code>、<code>options</code></td><td>选项块，按声明顺序编号，可使用 <code>c0: 文案</code>，也可用含 <code>label</code> 的子块</td></tr><tr><td><code>invert</code></td><td>对二选一选项的显示索引和值进行 <code>1 - value</code> 转换，常见于布尔设置</td></tr><tr><td><code>action</code></td><td><code>button</code> 调用的内部动作</td></tr><tr><td><code>offsetY</code></td><td>数值滑块的垂直绘制偏移</td></tr><tr><td><code>notice</code></td><td>控件下方提示文案</td></tr><tr><td><code>noticeHeight</code>、<code>noticeGap</code></td><td>提示高度、提示之后的布局增量，默认 <code>50</code>、<code>58</code></td></tr><tr><td><code>effectiveDefault</code></td><td>原生默认值哨兵的有效回退，例如 <code>TitleBlurRadius</code> 的 <code>-1</code>；应按标准控件使用</td></tr><tr><td><code>display</code></td><td>数值滑块设为 <code>&quot;percent&quot;</code> 时，将标题中的数值显示为百分比</td></tr></tbody></table><h3 id="原生设置绑定-bind" tabindex="-1">原生设置绑定 bind <a class="header-anchor" href="#原生设置绑定-bind" aria-label="Permalink to &quot;原生设置绑定 bind&quot;">​</a></h3><p>以下 <strong>39 个</strong>绑定来自当前标准预设的完整控件集合，大小写需一致。原生设置与通用视图属性是不同层次，例如 <code>cornerRad</code> 是窗口设置，<code>radius</code> 是某个图元的圆角。</p><table tabindex="0"><thead><tr><th><code>bind</code></th><th>类型/值与用途</th></tr></thead><tbody><tr><td><code>CompatibleLayer</code></td><td><code>0..4</code>；默认、静态、模糊、透明、扩展渲染层</td></tr><tr><td><code>BackgroundColor</code></td><td>COLORREF；收纳盒背景色</td></tr><tr><td><code>bgAlpha</code></td><td><code>0..1</code>；收纳盒背景不透明度</td></tr><tr><td><code>DwmCornerPreference</code></td><td><code>0</code> 小圆角、<code>1</code> 普通圆角；DWM 圆角偏好</td></tr><tr><td><code>cornerRad</code></td><td>标准控件 <code>0..20</code>；窗口自定义圆角</td></tr><tr><td><code>EnableStaticMaterialLayerForD3D11</code></td><td>布尔；启用 D3D11 静态材质层</td></tr><tr><td><code>shadowBlur</code></td><td>标准控件 <code>0..32</code>；扩展窗口阴影模糊</td></tr><tr><td><code>shadowAlpha</code></td><td><code>0..1</code>；窗口阴影不透明度</td></tr><tr><td><code>shadowOffsetX</code>、<code>shadowOffsetY</code></td><td>标准控件 ±32；窗口阴影横纵偏移</td></tr><tr><td><code>TransparentFrameMode</code></td><td><code>0</code> 无边框、<code>1</code> 画布、<code>2</code> 原生、<code>3</code> 高光边框</td></tr><tr><td><code>BorderColor</code></td><td>COLORREF；窗口边框色</td></tr><tr><td><code>BorderOpacity</code></td><td><code>0..1</code>；窗口边框不透明度</td></tr><tr><td><code>TitleType</code></td><td>标准 <code>0</code> 经典、<code>1</code> 悬浮、<code>2</code> 胶囊；新声明路径支持 <code>0..65535</code>，扩展值需要自行声明样式</td></tr><tr><td><code>TitleBarColor</code></td><td>COLORREF；标题栏颜色</td></tr><tr><td><code>titleAlpha</code></td><td><code>0..1</code>；标题背景不透明度</td></tr><tr><td><code>TitleBlurRadius</code></td><td>标准控件 <code>0..32</code>；标题模糊半径；默认 <code>-1</code> 表示使用有效默认值</td></tr><tr><td><code>tagAlpha</code></td><td><code>0..1</code>；标签不透明度</td></tr><tr><td><code>tagTextAlpha</code></td><td><code>0..1</code>；标签文字不透明度</td></tr><tr><td><code>TagStyle</code></td><td>标准 <code>0</code> 贴纸、<code>1</code> 轮廓、<code>2</code> 荧光笔、<code>3</code> 纯色、<code>4</code> 文字；新路径支持 <code>0..65535</code>，扩展样式由预设声明</td></tr><tr><td><code>tagFontFamily</code></td><td>字符串；标签字体族</td></tr><tr><td><code>ShowDefaultFolderIcon</code></td><td>布尔；<code>false</code> 使用文件夹内容预览，<code>true</code> 使用系统文件夹图标</td></tr><tr><td><code>ShowTextPreview</code></td><td>布尔；是否显示文本预览</td></tr><tr><td><code>ShowMediaPreview</code></td><td>布尔；是否显示媒体预览</td></tr><tr><td><code>HideFileExtension</code></td><td><code>0</code> 显示扩展名、<code>1</code> 隐藏扩展名、<code>2</code> 隐藏全部文件名</td></tr><tr><td><code>FileNameColorMode</code></td><td><code>0</code> 主题、<code>1</code> 白色、<code>2</code> 黑色文字</td></tr><tr><td><code>TextRenderMode</code></td><td><code>0</code> 无阴影、<code>1</code> 厚阴影、<code>2</code> 轻阴影、<code>3</code> 主题阴影</td></tr><tr><td><code>ListDetailType</code></td><td><code>0</code> 大小、<code>1</code> 不显示详情、<code>2</code> 日期</td></tr><tr><td><code>fontFamily</code></td><td>字符串；文件名字体族</td></tr><tr><td><code>textSize</code></td><td>标准控件 <code>6..18</code>、步进 <code>0.5</code>；文件名字号</td></tr><tr><td><code>TextOmitOffset</code></td><td>标准控件 <code>-6..6</code>；文件名省略预算偏移</td></tr><tr><td><code>AllowTextWrapOverflow</code></td><td>布尔；允许文件名换行溢出</td></tr><tr><td><code>FadeOutSwitch</code></td><td>布尔；启用渐隐效果</td></tr><tr><td><code>AutoHideTitleBar</code></td><td><code>0</code> 自动显示、<code>1</code> 隐藏并重排、<code>2</code> 仅隐藏、<code>3</code> 始终显示</td></tr><tr><td><code>QuickExpandCollapse</code></td><td><code>0</code> 不使用快捷展开、<code>1</code> 双击、<code>2</code> 单击</td></tr><tr><td><code>CollapseDirection</code></td><td><code>0</code> 自动、<code>1</code> 向上、<code>2</code> 向下</td></tr><tr><td><code>AutoFade</code></td><td><code>0</code> 禁用、<code>1</code> 自动淡出、<code>2</code> 自动折叠</td></tr><tr><td><code>FolderOpenMode</code></td><td><code>0</code> 不启用内联、<code>1</code> 启用内联文件夹/文档查看</td></tr><tr><td><code>SwipeUpSearchEnabled</code></td><td>布尔；是否启用上滑搜索</td></tr></tbody></table><p>颜色控件还使用原生配套来源设置，见下一段；它们不是新增的 <code>bind</code> 项。不要随意把任意配置键填入 <code>bind</code>。</p><h3 id="原生颜色来源" tabindex="-1">原生颜色来源 <a class="header-anchor" href="#原生颜色来源" aria-label="Permalink to &quot;原生颜色来源&quot;">​</a></h3><p><code>BackgroundColor</code>、<code>BorderColor</code>、<code>TitleBarColor</code> 的颜色控件会同时处理配套来源选择：</p><table tabindex="0"><thead><tr><th>配套设置</th><th>用途</th></tr></thead><tbody><tr><td><code>CustomBackgroundColor</code>、<code>CustomBorderColor</code></td><td>布尔；背景/边框是否使用自定义颜色，由对应颜色控件管理</td></tr><tr><td><code>TitleBarColorSource</code></td><td><code>0</code> 主题、<code>1</code> 标签、<code>2</code> 自定义；标题栏颜色来源，由对应颜色控件管理</td></tr></tbody></table><h2 id="设置面板-panel" tabindex="-1">设置面板 Panel <a class="header-anchor" href="#设置面板-panel" aria-label="Permalink to &quot;设置面板 Panel&quot;">​</a></h2><p><code>Panel</code> 调整个性化设置窗口，不是收纳盒内容区。以下为当前面板读取的全部布局项，数值默认单位 DIP：</p><table tabindex="0"><thead><tr><th>属性</th><th>标准值与用途</th></tr></thead><tbody><tr><td><code>width</code>、<code>height</code></td><td><code>400</code>、<code>630</code>；设置窗口尺寸</td></tr><tr><td><code>top</code>、<code>globalTop</code></td><td><code>140</code>、<code>64</code>；普通/全局专用面板的内容起点</td></tr><tr><td><code>footer</code></td><td><code>70</code>；底部区域预留高度</td></tr><tr><td><code>margin</code>、<code>padding</code></td><td><code>20</code>、<code>16</code>；外侧留白与组内间距</td></tr><tr><td><code>header</code>、<code>gap</code></td><td><code>52</code>、<code>12</code>；分组标题高度与组间距</td></tr><tr><td><code>bodyTop</code>、<code>bodyBottom</code></td><td><code>14</code>、<code>16</code>；组内顶部、底部留白</td></tr><tr><td><code>contentTop</code>、<code>contentBottom</code></td><td><code>15</code>、<code>50</code>；滚动内容顶部与底部余量</td></tr><tr><td><code>labelHeight</code>、<code>labelSize</code>、<code>labelFade</code></td><td><code>18</code>、<code>12</code>、<code>45</code>；字段标题高度、字号与颜色调整量</td></tr><tr><td><code>optionY</code>、<code>optionHeight</code>、<code>optionSize</code>、<code>optionGap</code></td><td><code>20</code>、<code>36</code>、<code>14</code>、<code>65</code>；选项控件偏移、高度、字号和布局增量</td></tr><tr><td><code>sliderHeight</code>、<code>sliderGap</code>、<code>sliderFade</code></td><td><code>32</code>、<code>50</code>、<code>50</code>；滑块高度、布局增量、颜色调整量</td></tr><tr><td><code>toggleWidth</code>、<code>toggleHeight</code>、<code>toggleTextX</code>、<code>toggleGap</code></td><td><code>40</code>、<code>22</code>、<code>54</code>、<code>40</code>；开关大小、文字横偏移与布局增量</td></tr><tr><td><code>colorY</code>、<code>colorHeight</code>、<code>colorGap</code></td><td><code>22</code>、<code>34</code>、<code>70</code>；颜色来源切换控件的偏移、高度和布局增量</td></tr><tr><td><code>editorHeight</code>、<code>editorGap</code></td><td><code>200</code>、<code>210</code>；颜色编辑区域高度和布局增量</td></tr><tr><td><code>groupOpacity</code>、<code>groupHoverOpacity</code></td><td><code>0.35</code>、<code>0.45</code>；分组普通/悬停背景不透明度</td></tr></tbody></table><p>标准文件还声明 <code>Panel.background</code>、<code>Panel.groupBackground</code> 供表达式引用；当前面板绘制本身仍直接使用原生主题色，不会因只覆盖这两个声明就自动换色。</p><h2 id="原生组件兼容属性" tabindex="-1">原生组件兼容属性 <a class="header-anchor" href="#原生组件兼容属性" aria-label="Permalink to &quot;原生组件兼容属性&quot;">​</a></h2><p>旧预设的 <code>pogget.native.Background</code>、<code>pogget.native.Tag</code>、<code>pogget.native.VinaIcon</code>、<code>pogget.native.Behavior</code> 在 <code>view</code> 下向原生模型传递以下属性。它们不是新增图元，字段大小写与原生配置一致。相同含义的设置绑定已在上文解释；这里补充兼容路径本身的接受范围，避免与某个标准滑块的范围混淆。</p><table tabindex="0"><thead><tr><th><code>view</code> 属性</th><th>用途与兼容范围</th></tr></thead><tbody><tr><td><code>backgroundAlpha</code>、<code>titleAlpha</code>、<code>tagAlpha</code>、<code>tagTextAlpha</code></td><td>背景、标题、标签、标签文字不透明度，<code>0..1</code></td></tr><tr><td><code>CompatibleLayer</code>、<code>TransparentFrameMode</code>、<code>DwmCornerPreference</code></td><td>渲染层 <code>0..4</code>、边框模式 <code>0..3</code>、DWM 圆角偏好 <code>0..1</code></td></tr><tr><td><code>cornerRad</code></td><td>窗口圆角，<code>0..512</code></td></tr><tr><td><code>shadowBlur</code>、<code>shadowAlpha</code></td><td>窗口阴影模糊 <code>0..128</code>、不透明度 <code>0..1</code></td></tr><tr><td><code>shadowOffsetX</code>、<code>shadowOffsetY</code></td><td>窗口阴影偏移，±256</td></tr><tr><td><code>EnableStaticMaterialLayerForD3D11</code></td><td>静态材质层开关，<code>0/1</code></td></tr><tr><td><code>TitleType</code>、<code>TagStyle</code></td><td>标题、标签样式编号，<code>0..65535</code>，外观由对应声明实现</td></tr><tr><td><code>ShowDefaultFolderIcon</code>、<code>ShowTextPreview</code>、<code>ShowMediaPreview</code></td><td>默认文件夹图标、文本预览、媒体预览开关，<code>0/1</code></td></tr><tr><td><code>HideFileExtension</code>、<code>FileNameColorMode</code>、<code>ListDetailType</code></td><td>文件名显示、颜色、详情策略，分别为 <code>0..2</code>，含义同绑定表</td></tr><tr><td><code>TextRenderMode</code></td><td>文字阴影策略，<code>0..3</code></td></tr><tr><td><code>textSize</code></td><td>原生文件名字号，<code>6..72</code></td></tr><tr><td><code>TextOmitOffset</code></td><td>文件名省略预算偏移，<code>-6..6</code></td></tr><tr><td><code>AllowTextWrapOverflow</code>、<code>FadeOutSwitch</code></td><td>换行溢出、渐隐开关，<code>0/1</code></td></tr><tr><td><code>AutoHideTitleBar</code></td><td>自动隐藏标题策略，<code>0..3</code></td></tr><tr><td><code>QuickExpandCollapse</code>、<code>CollapseDirection</code>、<code>AutoFade</code></td><td>快捷展开、展开方向、自动隐藏行为，分别 <code>0..2</code></td></tr><tr><td><code>FolderOpenMode</code>、<code>SwipeUpSearchEnabled</code></td><td>内联模式、上滑搜索，<code>0/1</code></td></tr><tr><td><code>fontFamily</code>、<code>tagFontFamily</code></td><td>原生文件名、标签字体族字符串</td></tr><tr><td><code>BorderOpacity</code>、<code>TitleBlurRadius</code></td><td>原生颜色样式的边框不透明度、标题模糊半径，通常保留标准控件的合法范围与默认值策略</td></tr></tbody></table><h3 id="标准-vinaicon-的附加外观字段" tabindex="-1">标准 VinaIcon 的附加外观字段 <a class="header-anchor" href="#标准-vinaicon-的附加外观字段" aria-label="Permalink to &quot;标准 VinaIcon 的附加外观字段&quot;">​</a></h3><p>以下字段位于标准预设的 <code>VinaIcon.view</code>，由 <code>FileIconSurface</code> 读取；缺少新表面 slot 的旧预设也会读取这些字段。它们是该组件的样式参数，不能填写到 <code>bind</code>。</p><table tabindex="0"><thead><tr><th>字段</th><th>用途与标准控件范围</th></tr></thead><tbody><tr><td><code>IconBackground</code></td><td>布尔；启用图标背景</td></tr><tr><td><code>IconBackgroundColor</code></td><td>COLORREF；图标背景颜色</td></tr><tr><td><code>IconBackgroundOpacity</code>、<code>IconBackgroundHoverOpacity</code></td><td><code>0..1</code>；背景普通/悬停不透明度</td></tr><tr><td><code>IconBackgroundRadius</code></td><td><code>0..128</code>；图标背景圆角</td></tr><tr><td><code>IconBackgroundExpandX</code></td><td><code>0..64</code> DIP，步长 <code>1</code>，初始默认 <code>4</code>；向左、右各扩展此距离，背景总宽增加两倍该值，高度不变</td></tr><tr><td><code>IconBackgroundExpandY</code></td><td><code>0..64</code> DIP，步长 <code>1</code>，初始默认 <code>4</code>；向上、下各扩展此距离，背景总高增加两倍该值，宽度不变</td></tr><tr><td><code>IconBackgroundOffsetY</code></td><td><code>-64..64</code> DIP，步长 <code>1</code>，默认 <code>0</code>；正值向下、负值向上平移整个背景与边框，宽高不变，不移动位图和文件名</td></tr><tr><td><code>IconBackgroundExpand</code></td><td>旧版单值兼容入口；未单独覆盖的 X/Y 轴沿用此值，通常为 <code>4</code> DIP。标准面板已隐藏此控件，新修改使用 X/Y</td></tr><tr><td><code>IconBorder</code></td><td>布尔；启用图标边框</td></tr><tr><td><code>IconBorderColor</code></td><td>COLORREF；图标边框颜色</td></tr><tr><td><code>IconBorderWidth</code></td><td><code>0..8</code>；图标边框宽度</td></tr><tr><td><code>IconBorderOpacity</code></td><td><code>0..1</code>；图标边框不透明度</td></tr></tbody></table><p>标准面板的扩展滑块分别位于 <code>VinaIcon.ui.IconBackgroundExpandX</code> 和 <code>VinaIcon.ui.IconBackgroundExpandY</code>，Y 偏移滑块位于 <code>VinaIcon.ui.IconBackgroundOffsetY</code>，开启图标背景或图标边框时显示。背景与边框共用扩展及偏移后的表面；这不会放大或移动图标位图，也不会改变文件名布局、图标间距或点击区域。圆角上限为表面较短边的一半；旧预设没有 Y 偏移字段时按 <code>0</code> 处理。没有 X 偏移字段。</p><p>修改预设时，建议覆盖对应 <code>ui</code> 字段的 <code>default</code>，保留 <code>view</code> 与滑块的连接，见<a href="./../custom-vina.html#icon-background-axes">分别调整图标背景 X/Y</a>。已有的预设内保存值优先于默认值；只改一个方向时，仅覆盖该轴。旧保存值和旧依赖预设的 <code>IconBackgroundExpand</code> 覆盖仍可沿用，单独设置的轴（包括 <code>0</code>）优先。</p><p>本页按 <code>VinaStyle.hpp</code>、<code>VinaView.hpp</code>、<code>PoggetPersonalizationPanel.inl</code>、<code>PoggetPersonalizationRuntime.hpp</code> 和 <code>Pogget_Std.vina</code> 核对（2026-11-09）。<code>pressed</code>、<code>shadow</code>、<code>border</code>、<code>background</code>、<code>variants</code> 等同名子块属于保留元数据，不作为子视图绘制；当前普通外观使用上表扁平属性，不应把保留块名当成自动生效的样式接口。</p>',68)]))}const b=t(r,[["render",a]]);export{p as __pageData,b as default};
